<?php namespace App\Filament\Resources; use Filament\Actions\{CreateAction,DeleteAction,EditAction}; use Filament\Forms\Components\TextInput; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Model; abstract class TaxonomyResource extends AdminResource {protected static ?string $recordTitleAttribute='name';protected static string|\UnitEnum|null $navigationGroup='Référentiels';public static function form(Schema $s):Schema{return $s->components([TextInput::make('name')->required()->maxLength(255),TextInput::make('slug')->required()->alphaDash()->unique(ignoreRecord:true)]);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->searchable()->sortable(),TextColumn::make('slug')->searchable(),TextColumn::make('restaurants_count')->label('Restaurants')->counts('restaurants')->sortable(),TextColumn::make('updated_at')->label('Modifié')->since()->sortable()])->recordActions([EditAction::make(),DeleteAction::make()->requiresConfirmation()->visible(fn(Model $r)=>!$r->restaurants()->exists())])->defaultSort('name');}}
